library(tidyverse)
library(janitor)
library(broom)
dir.create("charts",showWarnings=FALSE)
patients <- read_csv("data/hospital_patients_raw.csv",show_col_types=FALSE) |> clean_names()
patients_clean <- patients |> distinct(patient_id,.keep_all=TRUE) |> mutate(age=replace_na(age,median(age,na.rm=TRUE)),treatment_cost_inr=replace_na(treatment_cost_inr,median(treatment_cost_inr,na.rm=TRUE)),gender=replace_na(gender,"Not recorded"),diagnosis=replace_na(diagnosis,"Not recorded"),across(c(department,admission_type,discharge_status),as.factor),recovered=if_else(discharge_status=="Recovered",1L,0L))
write_csv(patients_clean,"data/hospital_patients_clean.csv")
ggplot(patients_clean,aes(department,fill=department))+geom_bar(show.legend=FALSE)+theme_minimal();ggsave("charts/01_department_admissions_R.png",width=8,height=4,dpi=200)
ggplot(patients_clean,aes(age,fill=gender))+geom_histogram(bins=14,alpha=.6,position="identity")+theme_minimal();ggsave("charts/02_age_gender_R.png",width=8,height=4,dpi=200)
ggplot(patients_clean,aes(department,treatment_cost_inr))+geom_boxplot()+theme_minimal();ggsave("charts/03_cost_department_R.png",width=8,height=4,dpi=200)
ggplot(patients_clean,aes(treatment_duration_days,treatment_cost_inr,color=discharge_status))+geom_point()+theme_minimal();ggsave("charts/04_cost_duration_R.png",width=8,height=4,dpi=200)
ggplot(patients_clean,aes(treatment_duration_days,fill=admission_type))+geom_histogram()+facet_wrap(~department)+theme_minimal();ggsave("charts/05_duration_facets_R.png",width=8,height=5,dpi=200)
model <- glm(recovered~age+treatment_duration_days+treatment_cost_inr+department+admission_type+gender,data=patients_clean,family=binomial());tidy(model,conf.int=TRUE)|>write_csv("model_coefficients.csv");summary(model)
